  return (
    <>
      <TabBar activeTab={activeTab} />
      {activeTab === "people" ? (
        <div className="people-grid">
          {/* `.length === 0` is a boolean, so `&&` can never print a stray 0 */}
          {data.people.length === 0 && <p>No people are on file for this case.</p>}
